import{_ as t,o,c as i,a2 as a}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"Quick Notes","description":"","frontmatter":{"sidebar_position":1},"headers":[],"relativePath":"quick-notes/index.md","filePath":"quick-notes/index.md","lastUpdated":1794045383000}'),r={name:"quick-notes/index.md"};function l(n,e,s,d,c,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="quick-notes" tabindex="-1">Quick Notes <a class="header-anchor" href="#quick-notes" aria-label="Permalink to &quot;Quick Notes&quot;">​</a></h1><p>Quick Notes is a lightweight editor tool that lets you place TODO notes, bug markers, and reminders directly in the Viewport and Blueprint Editor. Stay organized, track issues, and never lose context — all without leaving Unreal Engine.</p><div class="info custom-block"><p class="custom-block-title">Actively Maintained</p><p>This plugin is actively maintained by Deblx. We provide bug fixes, Unreal Engine compatibility updates, and improvements as needed. See the <a href="https://changelog.deblx.com" target="_blank" rel="noreferrer">Deblx Changelog</a> for the latest releases.</p></div><h2 id="why-you-need-this-tool" tabindex="-1">Why You Need This Tool <a class="header-anchor" href="#why-you-need-this-tool" aria-label="Permalink to &quot;Why You Need This Tool&quot;">​</a></h2><p>Game development is complex. Bugs appear during playtesting, level designers spot issues mid-work, and ideas pop up at the worst moments. Instead of switching to external tools like Trello or sticky notes on your monitor, Quick Notes lets you pin notes exactly where the problem is — right in your scene or on a Blueprint node.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><h3 id="viewport-notes" tabindex="-1">Viewport Notes <a class="header-anchor" href="#viewport-notes" aria-label="Permalink to &quot;Viewport Notes&quot;">​</a></h3><ul><li>Right-click anywhere in the Viewport to place a sticky note at that exact world location</li><li>Notes appear as colored cards floating above their position with a connector line</li><li>Choose from TODO, BUG, INFO, or REMINDER categories</li><li>Set priority levels (Low, Medium, High)</li><li>Toggle &quot;Editor only&quot; to hide notes during Play-In-Editor</li></ul><h3 id="blueprint-notes" tabindex="-1">Blueprint Notes <a class="header-anchor" href="#blueprint-notes" aria-label="Permalink to &quot;Blueprint Notes&quot;">​</a></h3><ul><li>Right-click any Blueprint node to attach a note directly to it</li><li>Notes are linked to the specific node via GUID</li><li>Jump back to the exact Blueprint from the overview panel</li><li>Never lose track of which node needs work</li></ul><h3 id="overview-panel" tabindex="-1">Overview Panel <a class="header-anchor" href="#overview-panel" aria-label="Permalink to &quot;Overview Panel&quot;">​</a></h3><ul><li>View and manage all notes in one place under <strong>Tools &gt; Quick Notes</strong></li><li>Search notes by title or description</li><li>Filter by source (Viewport / Blueprint) and resolved status</li><li>Jump to any note with one click — camera focuses on Viewport notes, Blueprint editor opens for BP notes</li><li>Mark notes as resolved or delete them</li></ul><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><ul><li>Export all notes to a .txt file with a file picker dialog</li><li>Organized by source (Viewport / Blueprint) with category, priority, and context info</li><li>Perfect for sharing with your team or archiving before a milestone</li></ul><h3 id="error-codes-for-easy-support" tabindex="-1">Error Codes for Easy Support <a class="header-anchor" href="#error-codes-for-easy-support" aria-label="Permalink to &quot;Error Codes for Easy Support&quot;">​</a></h3><p>Quick Notes includes built-in diagnostic codes (QN-100 to QN-700). If something goes wrong, check the Output Log and share the QN code with us — we can identify the issue immediately.</p><h2 id="note-properties" tabindex="-1">Note Properties <a class="header-anchor" href="#note-properties" aria-label="Permalink to &quot;Note Properties&quot;">​</a></h2><p>Every note includes:</p><ul><li><strong>Title:</strong> Short summary of the note</li><li><strong>Description:</strong> Optional detailed text</li><li><strong>Category:</strong> TODO, BUG, INFO, or REMINDER (color-coded)</li><li><strong>Priority:</strong> Low, Medium, or High</li><li><strong>Source:</strong> Viewport (world position) or Blueprint (linked to a specific node via GUID)</li><li><strong>Resolved:</strong> Mark notes as done without deleting them</li></ul><h2 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical Details&quot;">​</a></h2><ul><li><strong>Supported Engine Versions:</strong> 5.1+</li><li><strong>Platforms:</strong> Windows, Mac, Linux</li><li><strong>Module Type:</strong> Editor Only (no runtime impact)</li><li><strong>Network Replicated:</strong> No</li><li><strong>Runtime Performance Impact:</strong> None — the plugin runs exclusively in the editor and is completely stripped from packaged/shipping builds</li></ul><h2 id="data-storage" tabindex="-1">Data Storage <a class="header-anchor" href="#data-storage" aria-label="Permalink to &quot;Data Storage&quot;">​</a></h2><ul><li>All data is local and project-specific — not included in version control by default</li><li>No external services, network calls, or cloud dependencies</li><li>Your notes stay private and secure</li></ul><h2 id="get-it-now" tabindex="-1">Get It Now <a class="header-anchor" href="#get-it-now" aria-label="Permalink to &quot;Get It Now&quot;">​</a></h2><p>Available on <a href="https://www.fab.com/de/sellers/Deblx" target="_blank" rel="noreferrer">Fab Marketplace</a></p>',25)])])}const g=t(r,[["render",l]]);export{p as __pageData,g as default};
